#!/usr/bin/env python3
"""
Human-in-the-Loop (HITL) Validation System
==========================================

This module provides human validation and approval workflow for AI-generated tests.
Supports both interactive validation and PR-based review processes.
"""

import json
import os
import subprocess
from pathlib import Path
from typing import Dict, List, Any, Optional
from datetime import datetime
import tempfile
import webbrowser

class HITLValidator:
    """Human-in-the-Loop test validation system"""

    def __init__(self, repo_path: Path):
        self.repo_path = repo_path
        self.artifacts_path = repo_path / "genai_artifacts"
        self.artifacts_path.mkdir(exist_ok=True)

    def create_validation_report(self, test_plan: Dict[str, Any], generated_files: List[Path]) -> Dict[str, Any]:
        """Create a comprehensive validation report for human review"""

        validation_report = {
            "metadata": {
                "generated_at": datetime.utcnow().isoformat() + "Z",
                "repository": str(self.repo_path),
                "total_files": len(generated_files),
                "validation_required": True
            },
            "test_plan_summary": {
                "language": test_plan.get("metadata", {}).get("language", "unknown"),
                "framework": test_plan.get("metadata", {}).get("framework", "unknown"),
                "targets": len(test_plan.get("target_analysis", {}).get("targets", [])),
                "approach": test_plan.get("test_strategy", {}).get("approach", "unknown")
            },
            "generated_tests": [],
            "validation_checklist": {
                "code_quality": {
                    "syntax_valid": None,
                    "follows_conventions": None,
                    "proper_imports": None,
                    "no_forbidden_patterns": None
                },
                "test_quality": {
                    "covers_edge_cases": None,
                    "tests_error_conditions": None,
                    "appropriate_assertions": None,
                    "follows_aaa_pattern": None
                },
                "safety": {
                    "no_external_calls": None,
                    "no_file_system_access": None,
                    "deterministic_tests": None,
                    "no_security_risks": None
                }
            },
            "human_review": {
                "reviewed_by": None,
                "reviewed_at": None,
                "approved": None,
                "comments": [],
                "required_changes": []
            }
        }

        # Analyze each generated test file
        for test_file in generated_files:
            if test_file.exists():
                file_analysis = self._analyze_test_file(test_file, test_plan)
                validation_report["generated_tests"].append(file_analysis)

        return validation_report

    def _analyze_test_file(self, test_file: Path, test_plan: Dict[str, Any]) -> Dict[str, Any]:
        """Analyze a single test file for validation"""

        try:
            content = test_file.read_text(encoding='utf-8')
        except Exception as e:
            return {
                "file": str(test_file),
                "error": f"Could not read file: {e}",
                "valid": False
            }

        analysis = {
            "file": str(test_file.relative_to(self.repo_path)),
            "size_bytes": len(content),
            "line_count": len(content.split('\n')),
            "issues": [],
            "warnings": [],
            "summary": {}
        }

        # Check for forbidden patterns
        forbidden = test_plan.get("forbidden", [])
        for pattern in forbidden:
            if pattern.lower() in content.lower():
                analysis["issues"].append(f"Forbidden pattern detected: {pattern}")

        # Basic quality checks
        if "import subprocess" in content or "import os.system" in content:
            analysis["issues"].append("Potentially unsafe imports detected")

        if "sleep" in content and "time.sleep" in content:
            analysis["warnings"].append("Sleep detected - tests may be non-deterministic")

        if "requests." in content or "urllib" in content:
            analysis["issues"].append("Network calls detected in tests")

        # Count test functions
        test_functions = [line for line in content.split('\n') if line.strip().startswith('def test_')]
        analysis["summary"]["test_functions"] = len(test_functions)

        # Check for pytest patterns
        has_pytest_imports = "import pytest" in content
        has_parametrize = "@pytest.mark.parametrize" in content
        has_raises = "pytest.raises" in content

        analysis["summary"]["pytest_patterns"] = {
            "imports": has_pytest_imports,
            "parametrized_tests": has_parametrize,
            "exception_testing": has_raises
        }

        return analysis

    def generate_validation_html(self, validation_report: Dict[str, Any]) -> Path:
        """Generate an interactive HTML report for human validation"""

        html_template = """
