        }}

        function rejectTests() {{
            const reviewer = document.getElementById('reviewer_name').value;
            const comments = document.getElementById('comments').value;

            if (!reviewer) {{
                alert('Please enter reviewer name');
                return;
            }}

            if (!comments) {{
                alert('Please provide comments explaining why tests were rejected');
                return;
            }}

            const result = {{
                approved: false,
                reviewer: reviewer,
                comments: comments,
                timestamp: new Date().toISOString(),
                checklist: getChecklistResults()
            }};

            document.getElementById('result').innerHTML = 
                '<div class="issue"><strong>❌ Tests Rejected</strong><br>' + 
