    def create_pr_for_review(self, test_plan: Dict[str, Any], generated_files: List[Path]) -> Optional[str]:
        """Create a GitHub PR with generated tests for team review"""

        # Check if this is a git repository
        if not (self.repo_path / ".git").exists():
            print("⚠️ Not a git repository - cannot create PR")
            return None

        try:
            # Create a new branch for the generated tests
            branch_name = f"genai/tests/{datetime.now().strftime('%Y%m%d-%H%M%S')}"

            # Switch to new branch
            subprocess.run(["git", "checkout", "-b", branch_name], cwd=self.repo_path, check=True)

            # Add generated test files
            for test_file in generated_files:
                if test_file.exists():
                    subprocess.run(["git", "add", str(test_file)], cwd=self.repo_path, check=True)

            # Add validation artifacts
            validation_files = self.artifacts_path.glob("*validation*")
            for val_file in validation_files:
                subprocess.run(["git", "add", str(val_file)], cwd=self.repo_path, check=True)

            # Create commit
            commit_message = f"feat: GenAI generated tests for {len(generated_files)} files\n\n"
            test_count = sum(len([line for line in file.read_text().split('\n') if 'def test_' in line]) for file in generated_files if file.exists())
            commit_message += f"Generated {test_count} test functions\n"
            commit_message += f"Language: {test_plan.get('metadata', {}).get('language', 'unknown')}\n"
            commit_message += f"Framework: {test_plan.get('metadata', {}).get('framework', 'unknown')}\n\n"
            commit_message += "📋 Review Checklist:\n"
            commit_message += "- [ ] All tests pass locally\n"
            commit_message += "- [ ] No forbidden patterns (sleep, network calls, etc.)\n"
            commit_message += "- [ ] Covers edge cases and error conditions\n"
            commit_message += "- [ ] Follows testing best practices\n"
            commit_message += "- [ ] Tests are deterministic and isolated\n"

            subprocess.run(["git", "commit", "-m", commit_message], cwd=self.repo_path, check=True)

            print(f"✅ Created branch: {branch_name}")
            print(f"📋 Review the generated tests and create a PR for team approval")

            return branch_name

        except subprocess.CalledProcessError as e:
            print(f"❌ Failed to create PR branch: {e}")
            return None

    def interactive_validation(self, test_plan: Dict[str, Any], generated_files: List[Path]) -> Dict[str, Any]:
        """Run interactive validation in terminal"""

        print("\\n" + "="*60)
        print("🧪 GenAI Test Validation - Human-in-the-Loop")
        print("="*60)

        validation_report = self.create_validation_report(test_plan, generated_files)

        print(f"\\n📊 Summary:")
        print(f"   Language: {validation_report['test_plan_summary']['language']}")
        print(f"   Framework: {validation_report['test_plan_summary']['framework']}")
        print(f"   Generated Files: {validation_report['metadata']['total_files']}")

        # Show each test file
        total_issues = 0
        for test_file in validation_report["generated_tests"]:
            print(f"\\n📄 {test_file['file']}")
            print(f"   Functions: {test_file.get('summary', {}).get('test_functions', 0)}")
            print(f"   Size: {test_file.get('size_bytes', 0)} bytes")

            if test_file.get('issues'):
                print(f"   ❌ Issues:")
                for issue in test_file['issues']:
                    print(f"      - {issue}")
                total_issues += len(test_file['issues'])

            if test_file.get('warnings'):
                print(f"   ⚠️ Warnings:")
                for warning in test_file['warnings']:
                    print(f"      - {warning}")

        # Interactive approval
        print(f"\\n🔍 Validation Results:")
        if total_issues == 0:
            print("   ✅ No critical issues detected")
        else:
            print(f"   ❌ {total_issues} issues found")

        while True:
            response = input("\\n✋ Human Decision [approve/reject/view/help]: ").lower().strip()

            if response == 'approve':
                reviewer = input("👤 Enter your name: ").strip()
                comments = input("💬 Comments (optional): ").strip()

                approval = {
                    "approved": True,
                    "reviewer": reviewer,
                    "comments": comments,
                    "timestamp": datetime.utcnow().isoformat() + "Z",
                    "total_issues": total_issues
                }

                validation_report["human_review"] = approval

                # Save approval
                approval_file = self.artifacts_path / "human_approval.json"
                approval_file.write_text(json.dumps(approval, indent=2))

                print(f"\\n✅ Tests approved by {reviewer}")
                return validation_report

            elif response == 'reject':
                reviewer = input("👤 Enter your name: ").strip()
                reason = input("❌ Reason for rejection (required): ").strip()

                if not reason:
                    print("Please provide a reason for rejection")
                    continue

                rejection = {
                    "approved": False,
                    "reviewer": reviewer,
                    "comments": reason,
                    "timestamp": datetime.utcnow().isoformat() + "Z",
                    "total_issues": total_issues
                }

                validation_report["human_review"] = rejection

                # Save rejection
                rejection_file = self.artifacts_path / "human_rejection.json"
                rejection_file.write_text(json.dumps(rejection, indent=2))

                print(f"\\n❌ Tests rejected by {reviewer}")
                print(f"Reason: {reason}")
                return validation_report

            elif response == 'view':
                # Generate and open HTML report
                html_file = self.generate_validation_html(validation_report)
                print(f"\\n📋 Generated validation report: {html_file}")

                try:
                    webbrowser.open(f"file://{html_file.absolute()}")
                    print("🌐 Opened in browser")
                except:
                    print("📁 Open the file manually in a browser")

            elif response == 'help':
                print(f"""
📋 Commands:
   approve  - Approve the generated tests
   reject   - Reject the tests with reason
   view     - Open detailed HTML report in browser
   help     - Show this help message
                """)
            else:
                print("Invalid command. Type 'help' for available commands.")

