        host = os.environ.get("OLLAMA_HOST", "http://localhost:11434")

        print(f"Using LLM model: {model}")
        print(f"Ollama host: {host}")

        # Test connection to Ollama API
        import requests
        try:
            response = requests.get(f"{host}/api/tags", timeout=10)
            if response.status_code != 200:
                plan["integration_status"] = "connection_failed"
                plan["error"] = f"Ollama API returned status {response.status_code}"
                plan_path.write_text(json.dumps(plan, indent=2))
                print(f"❌ Cannot connect to Ollama API: HTTP {response.status_code}")
                return {"generated": False, "plan_file": str(plan_path), "reason": "connection_failed"}
        except Exception as e:
            plan["integration_status"] = "connection_error"
            plan["error"] = str(e)
            plan_path.write_text(json.dumps(plan, indent=2))
            print(f"❌ Ollama connection error: {e}")
            return {"generated": False, "plan_file": str(plan_path), "reason": f"connection_error: {e}"}

        # Set environment for LLM generation
        env = os.environ.copy()
        env["OLLAMA_MODEL"] = model
        env["OLLAMA_HOST"] = host

        # Create enhanced context bundle with diff detection
        bundle_path = ARTIFACTS / "context_bundle.json"
        context_path = ARTIFACTS / "context.json"

        if context_path.exists():
            print("Building enhanced context bundle with diff detection...")

            # Use the enhanced diff context builder  
            sys.path.insert(0, str(ROOT / "tools"))

            try:
                from diff_context_builder import build_enhanced_bundle

                with open(context_path) as f:
                    context_data = json.load(f)

                # Build enhanced bundle with git diff detection
                bundle_data = build_enhanced_bundle(ROOT, context_data)

                # Save bundle
                bundle_path.write_text(json.dumps(bundle_data, indent=2))
                print(f"✅ Enhanced context bundle created: {bundle_path}")
                print(f"   Mode: {bundle_data.get('mode', 'UNKNOWN')}")
                print(f"   Files: {len(bundle_data.get('files', []))}")

                if bundle_data.get('mode') == 'PR_ANALYSIS':
                    changed_files = bundle_data.get('git_info', {}).get('changed_files', [])
                    print(f"   Changed files: {changed_files}")

            except ImportError as e:
                print(f"⚠️ Enhanced diff detection failed: {e}")
                # Fallback to basic bundle creation
                bundle_data = {"files": [], "context": context_data, "targets": {}}
                for file_info in context_data.get("files", []):
                    if file_info.get("path", "").endswith(".py"):
                        file_path = ROOT / file_info["path"]
                        if file_path.exists():
                            bundle_data["files"].append({
                                "path": file_info["path"],
                                "full_text": file_path.read_text(encoding="utf-8", errors="ignore")[:20000],
                                "unified_diff": ""
                            })
                bundle_path.write_text(json.dumps(bundle_data, indent=2))
                print(f"Created basic context bundle: {bundle_path}")

        # Run LLM test generation
        generation_result = run(f"python {ROOT / 'llm_agent' / 'generate_tests.py'}", 
                              allow_fail=True, cwd=ROOT, env=env)

        if generation_result["success"]:
            plan["integration_status"] = "completed"
            plan["generation_output"] = generation_result["stdout"]
            plan["model_used"] = model
            plan_path.write_text(json.dumps(plan, indent=2))
            print("✅ LLM test generation completed successfully")
            return {"generated": True, "plan_file": str(plan_path), "output": generation_result["stdout"]}
        else:
            plan["integration_status"] = "generation_failed"
            plan["error"] = generation_result["stderr"]
            plan_path.write_text(json.dumps(plan, indent=2))
            print(f"❌ LLM generation failed: {generation_result['stderr']}")
            return {"generated": False, "plan_file": str(plan_path), "reason": "generation_failed"}

    except Exception as e:
        plan["integration_status"] = "error"
        plan["error"] = str(e)
        plan_path.write_text(json.dumps(plan, indent=2))
        print(f"❌ LLM integration error: {e}")
        return {"generated": False, "plan_file": str(plan_path), "reason": f"integration_error: {e}"}

def run_native_tests(stack: str) -> Dict[str, Any]:
    """Execute native test framework for the detected stack"""
    print(f"Running native tests for {stack} stack...")

    if stack == "python":
        # Try pytest first, fallback to unittest
        if (ROOT / "pytest.ini").exists() or any(ROOT.rglob("test_*.py")) or any(ROOT.rglob("*_test.py")):
            cmd = "python -m pytest -v --tb=short --disable-warnings --maxfail=5 --cov=. --cov-report=xml:coverage.xml --cov-report=term-missing --junit-xml=test-results.xml"
        else:
            cmd = "python -m unittest discover -s . -p 'test_*.py' -v"

    elif stack == "node":
        # Check for test script in package.json
        package_json = ROOT / "package.json"
        if package_json.exists():
            try:
                with open(package_json) as f:
                    pkg = json.load(f)
                if "scripts" in pkg and "test" in pkg["scripts"]:
                    cmd = "npm test"
                else:
                    cmd = "npx jest --runInBand --coverage --ci --testResultsProcessor=jest-junit"
            except:
                cmd = "npx jest --runInBand --coverage --ci"
        else:
            cmd = "npx jest --runInBand --coverage --ci"

    elif stack == "java":
        # Prefer Maven, fallback to Gradle
        if (ROOT / "pom.xml").exists():
            cmd = "mvn -B test -Dmaven.test.failure.ignore=true"
        elif any((ROOT / f).exists() for f in ["build.gradle", "build.gradle.kts"]):
            if (ROOT / "gradlew").exists():
                cmd = "./gradlew test --continue"
            else:
                cmd = "gradle test --continue"
        else:
            return {
                "cmd": "no_build_file",
                "returncode": 1,
                "duration_sec": 0,
                "stdout": "",
                "stderr": "No Maven pom.xml or Gradle build file found",
                "success": False
            }

    else:
        print(f"Unknown stack '{stack}', cannot run tests")
        return {
            "cmd": f"echo 'Unknown stack: {stack}'",
            "returncode": 0,
            "duration_sec": 0,
            "stdout": f"Unknown stack: {stack}. No tests executed.",
            "stderr": "",
            "success": True
        }

    return run(cmd, allow_fail=True)  # 15 min timeout for tests

def collect_test_reports(stack: str) -> List[str]:
    """Collect test and coverage reports based on stack"""
    print("Collecting test reports and artifacts...")

    collected_files = []

    # Common patterns by stack
    patterns = {
        "python": [
            "coverage.xml", "test-results.xml", ".coverage",
            "htmlcov/**/*", "pytest_cache/**/*"
        ],
        "node": [
            "coverage/**/*", "junit.xml", "jest-junit.xml", 
            "test-results.xml", "node_modules/.cache/jest/**/*"
        ],
        "java": [
            "target/site/jacoco/**/*", "target/surefire-reports/**/*",
            "build/reports/tests/**/*", "build/test-results/**/*",
            "build/reports/jacoco/**/*"
        ]
    }

    # Stack-specific collection  
    for pattern in patterns.get(stack, []):
        try:
            if "**" in pattern:
                # Recursive glob - handle recursion limit
                base_pattern = pattern.replace("**/*", "**")
                for path in ROOT.rglob(base_pattern.replace("**", "*")):
                    if path.is_file():
                        collected_files.append(str(path.relative_to(ROOT)))
            else:
                # Simple file check
                path = ROOT / pattern
                if path.exists():
                    collected_files.append(str(path.relative_to(ROOT)))
        except (OSError, RecursionError) as e:
            print(f"Error collecting pattern {pattern}: {e}")
            continue

    # Always include our artifacts
    for artifact in ARTIFACTS.rglob("*"):
        if artifact.is_file():
            collected_files.append(str(artifact.relative_to(ROOT)))

    # Create manifest
    manifest_path = ARTIFACTS / "collected_files_manifest.txt"
    manifest_path.write_text("\n".join(sorted(collected_files)))

    print(f"Collected {len(collected_files)} artifact files")
    return collected_files

def generate_summary_report(report_data: Dict[str, Any]) -> str:
    """Generate human-readable summary"""
    stack = report_data["stack"]
    duration = report_data.get("total_duration_sec", 0)

    summary = f"""
# GenAI Test Platform - Execution Summary

**Repository**: {ROOT.name}
**Stack**: {stack.upper()}
**Duration**: {duration:.1f} seconds
**Timestamp**: {report_data["started_at"]}

## Phase Results

"""

    for step in report_data.get("steps", []):
        phase = step["phase"]
        if phase == "deps":
            results = step["results"]
            failed = sum(1 for r in results if not r.get("success", True))
            summary += f"### Dependencies ({phase})\n"
            summary += f"- Commands executed: {len(results)}\n"
            summary += f"- Failed: {failed}\n"
            summary += f"- Status: {'✅ Success' if failed == 0 else '⚠️ Some failures'}\n\n"

        elif phase == "native_tests":
            result = step["result"]
            summary += f"### Test Execution ({phase})\n"
            summary += f"- Command: `{result['cmd']}`\n"
            summary += f"- Duration: {result['duration_sec']:.1f}s\n"
            summary += f"- Exit code: {result['returncode']}\n"
            summary += f"- Status: {'✅ Success' if result['success'] else '❌ Failed'}\n\n"

        elif phase == "genai":
            result = step["result"]
            summary += f"### AI Test Generation ({phase})\n"
            summary += f"- Enabled: {'Yes' if result['generated'] else 'No'}\n"
            if not result['generated']:
                summary += f"- Reason: {result.get('reason', 'Unknown')}\n"
            summary += f"- Plan file: `{result['plan_file']}`\n\n"

    summary += f"## Artifacts\n\n"
    summary += f"Collected {len(report_data.get('artifacts', []))} files for upload.\n\n"

    summary += f"---\n*Generated by GenAI Test Platform v2.0*"

    return summary

def main():
    """Main execution function"""
    parser = argparse.ArgumentParser(description="GenAI Test Platform - Unified Test Runner")
    parser.add_argument("--no-llm", action="store_true", help="Disable LLM test generation")
    parser.add_argument("--skip-validation", action="store_true", help="Skip human validation of generated tests")
    parser.add_argument("--stack", choices=["python", "node", "java"], help="Override stack detection")
    parser.add_argument("--timeout", type=int, default=1800, help="Total timeout in seconds (default: 30min)")

    args = parser.parse_args()

    start_time = time.time()

    print("Starting GenAI Test Platform - Unified Test Runner")
    print(f"Working directory: {ROOT}")

    # Initialize report
    report = {
        "started_at": datetime.utcnow().isoformat() + "Z",
        "runner_version": "2.0.0",
        "working_directory": str(ROOT),
        "arguments": vars(args),
        "stack": None,
        "steps": [],
        "artifacts": [],
        "summary": ""
    }

    try:
        # Phase 1: Stack Detection
        stack = detect_stack(args.stack)
        report["stack"] = stack

        # Phase 2: Dependencies
        print("Phase 2: Installing dependencies...")
        deps_results = ensure_dependencies(stack)
        report["steps"].append({"phase": "deps", "results": deps_results})

        # Phase 3: LLM Generation (optional)
        print("Phase 3: AI test generation...")
        llm_result = llm_generate_or_patch_tests(stack, not args.no_llm)
        report["steps"].append({"phase": "genai", "result": llm_result})

        # Phase 3.5: Human Validation (if tests were generated)
        validation_result = {"validated": False, "approved": None}
        if llm_result.get("generated") and not args.skip_validation:
            print("Phase 3.5: Human validation of AI-generated tests...")
            try:
                # First, run a minimal file-location check so humans know exactly where
                # generated tests were written. This prints file paths and prompts the
                # human to inspect them before approving. The helper saves the
                # decision to genai_artifacts/human_manual_approval.json.
                hf_cmd = f'{sys.executable} "{ROOT / "tools" / "human_file_check.py"}"'
                print(f"Running manual file-check helper: {hf_cmd}")
                hf_res = run(hf_cmd, cwd=ROOT, allow_fail=True)

                # If helper recorded a rejection, stop immediately
                if not hf_res.get("success"):
                    # helper exit codes: 0=approved, 2=non-interactive no-auto, 3=rejected
                    rc = hf_res.get("returncode")
                    # Try to read approval artifact if present
                    approval_path = ARTIFACTS / "human_manual_approval.json"
                    if approval_path.exists():
                        approval = json.loads(approval_path.read_text())
                        validation_result = {"validated": True, "report": approval}
                        report["steps"].append({"phase": "validation_manual_check", "result": validation_result})
                        if approval.get("approved") is False:
                            print("❌ Tests were rejected during manual file check - stopping execution")
                            report["success"] = False
                            report["error"] = "Tests rejected during manual file check"
                            return report
                    else:
                        # No artifact; treat as manual approval required and stop
                        print("⚠️ Manual file check did not complete successfully and no approval artifact found. Stopping.")
                        report["steps"].append({"phase": "validation_manual_check", "result": hf_res})
                        report["success"] = False
                        report["error"] = "Manual file check required"
                        return report

                # If helper succeeded (exit 0), proceed to richer validation if configured
                from hitl_validator import HITLValidator
                validator = HITLValidator(ROOT)

                # Find generated test files
                test_files = []
                if stack == "python":
                    test_files = list(ROOT.rglob("test_*.py")) + list(ROOT.rglob("*_test.py"))
                elif stack == "node":
                    test_files = list(ROOT.rglob("*.test.js")) + list(ROOT.rglob("*.spec.js"))
                elif stack == "java":
                    test_files = list(ROOT.rglob("*Test.java"))

                # Load test plan if available
                plan_path = ARTIFACTS / "genai_test_plan.json"
                test_plan = {}
                if plan_path.exists():
                    test_plan = json.loads(plan_path.read_text())

                # Run validation based on mode
                validation_mode = os.environ.get("HITL_MODE", "interactive")

                if validation_mode == "interactive":
                    validation_report = validator.interactive_validation(test_plan, test_files)
                elif validation_mode == "pr_review":
                    branch = validator.create_pr_for_review(test_plan, test_files)
                    validation_report = {
                        "mode": "pr_review", 
                        "branch": branch,
                        "approved": None,  # Pending PR approval
                        "message": "Tests submitted for PR review"
                    }
                else:
                    # Auto-approve or skip validation
                    validation_report = {
                        "mode": "auto_approve",
                        "approved": True,
                        "message": "Auto-approved (validation skipped)"
                    }

                validation_result = {"validated": True, "report": validation_report}

                # If rejected, stop execution
                if validation_report.get("approved") == False:
                    print("❌ Tests rejected by human reviewer - stopping execution")
                    report["steps"].append({"phase": "validation", "result": validation_result})
                    report["success"] = False
                    report["error"] = "Tests rejected during human validation"
                    return report

                print("✅ Human validation completed")

            except ImportError:
                print("⚠️ HITL validator not available, skipping validation")
                validation_result["error"] = "HITL validator not imported"
            except Exception as e:
                print(f"⚠️ Validation failed: {e}")
                validation_result["error"] = str(e)

        report["steps"].append({"phase": "validation", "result": validation_result})

        # Phase 4: Native Tests
        print("Phase 4: Running native tests...")
        test_result = run_native_tests(stack)
        report["steps"].append({"phase": "native_tests", "result": test_result})

        # Phase 5: Artifact Collection
        print("Phase 5: Collecting artifacts...")
        artifacts = collect_test_reports(stack)
        report["artifacts"] = artifacts

        # Finalize report
        report["finished_at"] = datetime.utcnow().isoformat() + "Z"
        report["total_duration_sec"] = round(time.time() - start_time, 3)
        report["success"] = True

    except Exception as e:
        print(f"Execution failed: {e}", file=sys.stderr)
        report["error"] = str(e)
        report["success"] = False
        report["finished_at"] = datetime.utcnow().isoformat() + "Z"
        report["total_duration_sec"] = round(time.time() - start_time, 3)

    # Generate summary
    summary = generate_summary_report(report)
    report["summary"] = summary

    # Save reports
    report_file = ARTIFACTS / "test_report.json"
    summary_file = ARTIFACTS / "summary.md"

    report_file.write_text(json.dumps(report, indent=2))
    summary_file.write_text(summary)

    print(f"Execution completed in {report['total_duration_sec']:.1f}s")
    print(f"Report saved: {report_file}")
    print(f"Summary saved: {summary_file}")

    # Exit with appropriate code
    if report.get("success", False):
        sys.exit(0)
    else:
        sys.exit(1)

if __name__ == "__main__":
    main()
